-- t270 rollback — recreate the two grain-sink tables (exact live structure captured
-- pre-drop). A code-revert of #1226 (uns.go provisionMatrix + RefreshCurrentHour + the
-- equipment_live_week grain) then repopulates them.
CREATE TABLE silver.equipment_live_hour (id_equipment integer, oee real, oee_a real, oee_p real, oee_q real, gross_production real, net_production real, scrap real, speed real, target real, begin_time timestamptz, end_time timestamptz, idle_time integer, elapsed_time integer, idle_blocked integer, idle_starved integer, running_time integer, stopped_time integer, available_time integer, planned_downtime integer, ideal_production real, proportional_target real, proportional_ideal_production real, last_24_hours jsonb, gross_production_exec_mode real, net_production_exec_mode real, scrap_exec_mode real, last_updated timestamptz);

CREATE TABLE silver.equipment_live_week (id_equipment integer, oee real, oee_a real, oee_p real, oee_q real, gross_production real, net_production real, scrap real, speed real, target real, begin_time timestamptz, end_time timestamptz, idle_time bigint, elapsed_time bigint, idle_blocked bigint, idle_starved bigint, running_time bigint, stopped_time bigint, available_time bigint, planned_downtime bigint, ideal_production real, proportional_target real, proportional_ideal_production real, gross_production_exec_mode real, net_production_exec_mode real, scrap_exec_mode real, last_updated timestamptz);
